Here is the root cause:
The bug arises from accessing enum values using an integer type, which can lead to out-of-bounds access in arrays. This is particularly problematic on platforms like aarch64, where the size of a long integer (8 bytes) differs from the size of the enum (4 bytes), causing potential misalignment and incorrect memory access.

Here is the patch:

 static int rx_macro_mux_get(struct snd_kcontrol *kcontrol,
 			  struct snd_ctl_elem_value *ucontrol)
 {
 	struct snd_soc_dapm_widget *widget = snd_soc_dapm_kcontrol_widget(kcontrol);
 	struct snd_soc_component *component = snd_soc_dapm_to_component(widget->dapm);
 	struct rx_macro *rx = snd_soc_component_get_drvdata(component);

-	ucontrol->value.integer.value[0] =
+	ucontrol->value.enumerated.item[0] =
 			rx->rx_port_value[widget->shift];
 	return 0;
 }

 static int rx_macro_mux_put(struct snd_kcontrol *kcontrol,
 			    struct snd_ctl_elem_value *ucontrol)
 {
 	struct snd_soc_dapm_widget *widget = snd_soc_dapm_kcontrol_widget(kcontrol);
 	struct snd_soc_component *component = snd_soc_dapm_to_component(widget->dapm);
 	struct soc_enum *e = (struct soc_enum *)kcontrol->private_value;
 	struct snd_soc_dapm_update *update = NULL;
-	u32 rx_port_value = ucontrol->value.integer.value[0];
+	u32 rx_port_value = ucontrol->value.enumerated.item[0];
 	u32 aif_rst;
 	struct rx_macro *rx = snd_soc_component_get_drvdata(component);

 	aif_rst = rx->rx_port_value[widget->shift];
 	if (!rx_port_value) {
 		if (aif_rst == 0) {
 			dev_err(component->dev, "%s:AIF reset already\n", __func__);
 			return 0;
 		}
 		if (aif_rst > RX_MACRO_AIF4_PB) {
 			dev_err(component->dev, "%s: Invalid AIF reset\n", __func__);
 			return 0;
 		}
 	}
 	rx->rx_port_value[widget->shift] = rx_port_value;

 	switch (rx_port_value) {
 	case 0:
 		if (rx->active_ch_cnt[aif_rst]) {
 			clear_bit(widget->shift,
 				&rx->active_ch_mask[aif_rst]);
 			rx->active_ch_cnt[aif_rst]--;
 		}
 		break;
 	case 1:
 	case 2:
 	case 3:
 	case 4:
 		set_bit(widget->shift,
 			&rx->active_ch_mask[rx_port_value]);
 		rx->active_ch_cnt[rx_port_value]++;
 		break;
 	default:
 		dev_err(component->dev,
 			"%s:Invalid AIF_ID for RX_MACRO MUX %d\n",
 			__func__, rx_port_value);
 		goto err;
 	}

 	snd_soc_dapm_mux_update_power(widget->dapm, kcontrol,
 					rx_port_value, e, update);
 	return 0;
 err:
 	return -EINVAL;
 }


